using System.Text.Json;using ToneCustoms.ShellStudio.Bridges;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Export;
public sealed class GtaExportCoordinator { readonly BlenderBridge blender=new();public async Task<ExportDiagnostics> RunAsync(ShellProject p,string blenderExe,string bridgeScript,string output){var d=new ExportDiagnostics();Directory.CreateDirectory(output);var payload=Path.Combine(output,"shellstudio-export.tcshell");await File.WriteAllTextAsync(payload,JsonSerializer.Serialize(p,new JsonSerializerOptions{WriteIndented=true}));var r=await blender.RunHeadlessAsync(blenderExe,null,bridgeScript,payload,output);var log=new BridgeLog().Write("blender",r.StdOut+Environment.NewLine+r.StdErr);d.Add("Blender/Sollumz bridge",r.ExitCode==0,r.ExitCode==0?"Bridge completed":"Bridge failed with exit code "+r.ExitCode,log);var status=Path.Combine(output,"bridge-status.json");d.Add("Bridge status",File.Exists(status),File.Exists(status)?"Status generated":"Status missing");return d;} }
